/**
 * `@pantoken/components` — an InstUI-look CSS component library, built from the `--instui-*` tokens.
 *
 * The shipped stylesheets:
 *
 * - **Base** ({@link baseCss}) — opt-in global document defaults from the tokens (box-sizing, body
 *   reset, page surface, base text colour/font, `color-scheme`). It also carries the focus-outline
 *   ring, so every focusable gets an accessible `:focus-visible` outline out of the box. Load it when
 *   pantoken owns the page.
 * - **Prose** ({@link proseCss}) — styles rendered markdown/prose HTML (tables, headings, links,
 *   lists, code) scoped to a content root, so a docs page or content region looks like InstUI
 *   without swapping the DOM for components. This is what the site renderers ship as their
 *   `components.css`.
 * - **Components** ({@link buttonCss}, {@link alertCss}, {@link badgeCss}, aggregated by
 *   {@link componentsCss}) — class-based component styles you apply to your own markup
 *   (`<button class="instui-button">`), for the InstUI look outside a component framework. The
 *   `--instui-elevation-*` shadow scale ({@link elevationCss}) leads this sheet, since enough
 *   components float that shadows are an intrinsic design attribute rather than an add-on.
 * - **Utilities** ({@link viewCss}, {@link spacingUtilitiesCss}, {@link layoutUtilitiesCss}, plus a
 *   curated semantic-colour/token set) — an opt-in layer of cross-cutting classes. The generic
 *   token→class emitters (`colorUtilitiesCss`, `tokenUtilitiesCss`) live in `@pantoken/utils`; this
 *   package feeds them the curated *semantic* names, while `@pantoken/plugin-primitives` feeds the raw
 *   palette.
 * - **Fonts** (opt-in `fonts.css`) — the `@font-face` rules for the Instructure brand fonts. Base
 *   *applies* the font; `fonts.css` *loads* the woff2s, so text degrades gracefully without it.
 *
 * Everything is pure CSS derived from the token IR, so it tracks InstUI through the tokens with no
 * dependency on the InstUI React packages. For the real, interactive components, use
 * `@pantoken/react-markdown` (content) or `@instructure/ui-*` (apps).
 *
 * This module is a barrel: each documented record lives in its own file under
 * `components/`/`utilities/`/`rules/`/`declarations/`, authored with the `lib/` compose API. The
 * registries (`COMPONENTS`/`UTILITIES`/`RULES`/`DECLARATIONS`) drive aggregation + the parity test.
 *
 * @module
 * @beta
 */
import { COMPONENTS } from "./components/index.ts";
import { elevationCss } from "./declarations/elevation.ts";
import { ns, type ComponentOptions } from "./lib/helpers.ts";
import { base } from "./rules/base.ts";
import { focusOutlineCss } from "./declarations/focus.ts";

// ── Shared options + prefix ─────────────────────────────────────────────────
export { DEFAULT_PREFIX, type ComponentOptions } from "./lib/helpers.ts";

// ── Rules ───────────────────────────────────────────────────────────────────
export { proseCss, type ProseOptions } from "./rules/prose.ts";

/**
 * Build the opt-in base/reset stylesheet: global document defaults from the tokens (box-sizing, body
 * reset, page surface, base text colour/font, `color-scheme`, base link), followed by the focus ring
 * (a document-level default that targets bare focusables). Load it once, ahead of the component and
 * prose sheets, when pantoken owns the page.
 *
 * @returns The CSS string.
 */
export function baseCss(): string {
  return `/* InstUI-look base/reset (@pantoken/components) */\n${base.rules("").trim()}\n\n${focusOutlineCss()}`;
}

// ── Declarations ────────────────────────────────────────────────────────────
export { ELEVATION_NAMES, elevationCss, elevationDeclarations } from "./declarations/elevation.ts";
export {
  FOCUSABLE_SELECTOR,
  focusOutlineCss,
  focusOutlineDeclarations,
  focusOutlineRules,
} from "./declarations/focus.ts";

// ── Components ──────────────────────────────────────────────────────────────
export { buttonCss } from "./components/button.ts";
export { alertCss } from "./components/alert.ts";
export { badgeCss } from "./components/badge.ts";
export { pillCss } from "./components/pill.ts";
export { tagCss } from "./components/tag.ts";
export { avatarCss } from "./components/avatar.ts";
export { tabsCss } from "./components/tabs.ts";
export { metricCss } from "./components/metric.ts";
export { imgCss } from "./components/img.ts";
export { bylineCss } from "./components/byline.ts";
export { tableCss } from "./components/table.ts";
export { linkCss } from "./components/link.ts";
export { listCss } from "./components/list.ts";
export { checkboxCss } from "./components/checkbox.ts";
export { radioCss } from "./components/radio.ts";
export { spinnerCss } from "./components/spinner.ts";
export { progressCss } from "./components/progress.ts";
export { menuCss } from "./components/menu.ts";
export { modalCss } from "./components/modal.ts";
export { breadcrumbCss } from "./components/breadcrumb.ts";
export { billboardCss } from "./components/billboard.ts";
export { ratingCss } from "./components/rating.ts";
export { toggleGroupCss } from "./components/toggle-group.ts";
export { contextViewCss } from "./components/context-view.ts";
export { progressCircleCss } from "./components/progress-circle.ts";
export { paginationCss } from "./components/pagination.ts";
export { truncateCss } from "./components/truncate.ts";
export { toggleDetailsCss } from "./components/toggle-details.ts";
export { fileDropCss } from "./components/file-drop.ts";
export { sideNavBarCss } from "./components/side-nav-bar.ts";
export { treeBrowserCss } from "./components/tree-browser.ts";
export { calendarCss } from "./components/calendar.ts";
export { popoverCss } from "./components/popover.ts";
export { trayCss } from "./components/tray.ts";
export { tooltipCss } from "./components/tooltip.ts";
export { rangeInputCss } from "./components/range-input.ts";
export { headingCss } from "./components/heading.ts";
export { textCss } from "./components/text.ts";
export { closeButtonCss } from "./components/close-button.ts";
export { textInputCss } from "./components/text-input.ts";
export { textAreaCss } from "./components/text-area.ts";
export { simpleSelectCss } from "./components/simple-select.ts";
export { inputGroupCss } from "./components/input-group.ts";
export { numberInputCss } from "./components/number-input.ts";
export { inPlaceEditCss } from "./components/in-place-edit.ts";
export { formFieldMessagesCss } from "./components/form-field-messages.ts";
export { formFieldCss } from "./components/form-field.ts";
export { formFieldGroupCss } from "./components/form-field-group.ts";
export { radioInputGroupCss } from "./components/radio-input-group.ts";

// Bespoke: the experimental customizable-select enhancement (no cssdoc record).
export { selectCss } from "./components/select.ts";

// ── Utilities ───────────────────────────────────────────────────────────────
export { viewCss } from "./utilities/view.ts";
export { spacingUtilitiesCss } from "./utilities/spacing.ts";
export { layoutUtilitiesCss } from "./utilities/layout.ts";
export { responsiveUtilitiesCss } from "./utilities/responsive.ts";
export { iconCss } from "./utilities/icon.ts";
export { maskCss } from "./utilities/mask.ts";
export { screenReaderContentCss } from "./utilities/screen-reader-content.ts";
// Bespoke: the glyph-token half of the icon system (no cssdoc record).
export { iconGlyphsCss, type IconGlyphsOptions } from "./utilities/icon-glyphs.ts";

/**
 * Build the aggregated component stylesheet: the `--instui-elevation-*` scale (so shadows are intrinsic)
 * followed by every component's rules in the `COMPONENTS` concat order. The size-alias and
 * deprecated-alias twins are appended PER COMPONENT (within its own chunk) so each alias documents on
 * its own page — the deprecated aliases are discovered from each record's `@deprecated {@link -x}`
 * metadata (see `withAliases`), not a central hand-kept list.
 *
 * @param options - {@link ComponentOptions}.
 * @returns The CSS string.
 */
export function componentsCss(options: ComponentOptions = {}): string {
  const prefix = options.prefix || "";
  // Each record's rules() already appends its own size/deprecated-alias twins, so this is a plain concat.
  const rules = COMPONENTS.map((d) => d.rules(ns(prefix), options).trim());
  // Elevation tokens lead the sheet so the shadows components reference (modal, alert, menu) resolve
  // from components.css alone — elevation is an intrinsic design attribute here, not an add-on.
  return `/* InstUI component styles (@pantoken/components) — prefix: ${prefix} */\n${elevationCss()}\n${rules.join("\n\n")}\n`;
}

/**
 * Emit the default stylesheets for `@pantoken/components`:
 *
 * - `generated/base.css` — the opt-in global base/reset (document defaults).
 * - `generated/components.css` — the class-based components (button, alert, badge), `.instui-*`.
 * - `generated/prose.css` — the prose/content styling, scoped to `.pantoken-prose`.
 * - `generated/icons.css` — one `.instui-icon-<name>` glyph class per icon (large; kept separate).
 * - `generated/utilities.css` — cross-cutting spacing/colour utilities + the View primitive.
 *
 * Per-component CSS files (`generated/<name>.css`) are emitted separately by `scripts/build-entries.ts`
 * which only runs as part of `build`, not `generate`. This keeps the generate step (used by docs:dev)
 * from writing 46+ files on every hot-reload and triggering a workspace-observer loop.
 *
 * Consumers that need a different prefix or scope call `componentsCss({ prefix })` /
 * `proseCss({ scope })` and write their own file (the renderers do this for their content root).
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { icons } from "@pantoken/icons";
import { tokens } from "@pantoken/tokens";
import { colorUtilitiesCss, tokenUtilitiesCss } from "@pantoken/utils";
import { css } from "../src/lib/css.ts";
import { fontsCss } from "./fonts.ts";
import {
  baseCss,
  componentsCss,
  ELEVATION_NAMES,
  iconGlyphsCss,
  layoutUtilitiesCss,
  proseCss,
  responsiveUtilitiesCss,
  selectCss,
  spacingUtilitiesCss,
  viewCss,
} from "../src/index.ts";
const outDir = resolve(import.meta.dirname, "../generated");
mkdirSync(outDir, { recursive: true });

const writeIfChanged = (path: string, next: string): void => {
  try {
    const prev = readFileSync(path, "utf8");
    if (prev === next) return;
  } catch {
    // no-op: write below
  }
  writeFileSync(path, next);
};

// The shipped stylesheets carry the default `instui` prefix. The builders opt out of a prefix on any
// falsy value, so pass it explicitly here (the `prefix: null` opt-out is a consumer-side choice).
const opts = { prefix: "instui" } as const;

// The semantic colour "intents" worth exposing as override utilities — the surface/text/border
// vocabulary an author actually reaches for. This deliberately skips the control-state subtree
// (`interactive-*`), the data-viz palettes (`chart-*`), and one-off surfaces (`overlay-*`,
// `elevated-surface-*`, opacity, gradients): those aren't overrides you paint onto arbitrary elements.
const SEMANTIC_INTENTS = new Set([
  "base",
  "brand",
  "page",
  "container",
  "container-base",
  "container-dark",
  "dark",
  "muted",
  "strong",
  "success",
  "warning",
  "error",
  "info",
  "inverse",
  "on-color",
]);

// The semantic colour token names per family (the `--instui-color-*` layer — not primitives), kept to
// the intents above plus the full `accent-*` palette (ash…violet). Each name is intersected with the
// family's real tokens, so a utility is only ever emitted for a token that exists (e.g. no `fg-brand`,
// since there's no `--instui-color-text-brand`).
const names = (family: string): string[] => {
  const prefix = `--instui-color-${family}-`;
  return tokens
    .filter((t) => t.name.startsWith(prefix))
    .map((t) => t.name.slice(prefix.length))
    .filter((name) => SEMANTIC_INTENTS.has(name) || name.startsWith("accent-"))
    .sort();
};

// Full token names under a family prefix — fed to the token-to-class transformer, which maps each to
// its natural CSS property. One "family → one property" pass per group.
const family = (prefix: string): string[] =>
  tokens
    .filter((t) => t.name.startsWith(prefix))
    .map((t) => t.name)
    .sort();

// Semantic families that map cleanly to a single CSS property. Colour and spacing are excluded — they
// have bespoke builders (bg/fg/border, m/p) since one token maps to several properties there.
const tokenGroups = [
  { property: "font-family", tokens: family("--instui-font-family-") },
  { property: "font-weight", tokens: family("--instui-font-weight-") },
  { property: "line-height", tokens: family("--instui-line-height-") },
  { property: "border-radius", tokens: family("--instui-border-radius-") },
  { property: "border-width", tokens: family("--instui-border-width-") },
  { property: "opacity", tokens: family("--instui-opacity-") },
  // Elevation shadows are defined by elevationCss (in components.css), not the base IR; reference them.
  { property: "box-shadow", tokens: ELEVATION_NAMES.map((n) => `--instui-elevation-${n}`) },
];

writeFileSync(join(outDir, "base.css"), baseCss());
writeFileSync(join(outDir, "components.css"), componentsCss(opts));
// Internal (NOT shipped): every record in the `pfx-` authoring prefix — the cssdoc `providers` target
// (see formats/components/cssdoc.jsonc) that lets the per-file source-`.css` lint resolve sibling records
// named in `@structure` (e.g. tree-browser's `.pfx-icon`). Written under src/generated/ (gitignored),
// never added to the shipped sheets. cssdoc resolves siblings by record NAME/class, so this must carry
// EVERY record — including the TS-authored holdouts (button, heading, the input controls) that a plain
// concatenation of the `.css` sources would miss — which is exactly what `componentsCss` bundles.
const srcGenDir = resolve(import.meta.dirname, "../src/generated");
mkdirSync(srcGenDir, { recursive: true });
writeIfChanged(join(srcGenDir, "_records.css"), componentsCss({ prefix: "pfx" }));
// Opt-in font loading — @font-face rules for the brand typeface, src → the shipped assets/fonts/.
writeFileSync(join(outDir, "fonts.css"), fontsCss(resolve(import.meta.dirname, "../assets/fonts")));
writeFileSync(join(outDir, "prose.css"), proseCss());
// Opt-in EXPERIMENTAL customizable-select enhancement (@supports base-select) for .instui-simple-select.
writeFileSync(join(outDir, "select.css"), selectCss(opts));
writeFileSync(
  join(outDir, "icons.css"),
  iconGlyphsCss(
    icons.map((icon) => icon.name),
    { ...opts, deprecatedAliases: true },
  ),
);
// `colorUtilitiesCss` is a generic emitter (in @pantoken/utils), so its CSS-API doc comment is authored
// here, where the InstUI-semantic palette is fed in.
// prettier-ignore
const colorDoc = css`/**
 * @utility color
 * @class .instui-text-danger
 * @summary Semantic colour utilities: \`.instui-bg-<name>\`, \`.instui-text-<name>\`, and \`.instui-stroke-<name>\` for the curated semantic palette.
 * @example <p class="instui-text-danger">Something went wrong.</p>
 */\n`;
writeFileSync(
  join(outDir, "utilities.css"),
