(function(){
  // switch site theme to canvas (the palette selector writes this + localStorage)
  document.documentElement.dataset.pantokenTheme = 'canvas';
  localStorage.setItem('pantoken-theme','canvas');
  document.documentElement.classList.remove('dark');
  // find the canvas-scoped hover rule in the loaded stylesheets
  let found = null;
  for (const sheet of document.styleSheets) {
    let rules; try { rules = sheet.cssRules; } catch(e){ continue; }
    for (const r of rules) {
      if (r.selectorText && r.selectorText.includes('data-pantoken-theme="canvas"') &&
          r.selectorText.includes('billboard') && r.selectorText.includes('clickable') &&
          r.selectorText.includes(':hover')) {
        found = { selector: r.selectorText, border: r.style.getPropertyValue('border-color'), href: sheet.href };
      }
    }
  }
  return found;
})()

