(function(){
  // inject a temporary style that applies the same declaration without needing a real pointer hover,
  // by cloning the hover rule onto a forced class — purely to screenshot the effect.
  var el = document.querySelector('.instui-billboard.-clickable');
  if(!el) return 'no el';
  var probe = getComputedStyle(el).borderColor;
  el.classList.add('__force_hover_probe');
  var s = document.createElement('style');
  s.textContent = ':root[data-pantoken-theme="canvas"] .instui-billboard.-clickable.__force_hover_probe{border-color:red;border-style:dashed;}';
  document.head.appendChild(s);
  el.scrollIntoView({block:'center'});
  return { baseBorder: probe, forcedBorder: getComputedStyle(el).borderColor };
})()

