  let found = null;
  for (const sheet of document.styleSheets) {
    let rules; try { rules = sheet.cssRules; } catch(e){ continue; }
    for (const r of rules) {
      if (r.selectorText && r.selectorText.includes('data-pantoken-theme="canvas"') &&
          r.selectorText.includes('billboard') && r.selectorText.includes('clickable') &&
          r.selectorText.includes(':hover') && !r.selectorText.includes('__force')) {
        found = r.style.getPropertyValue('border-color');
      }
    }
  }
  return { canvasHoverBorder: found };
})()

