toolUseResult.originalFile:
/**
 * Emit `.vitepress/theme/generated/site-themes.css` — the whole-site theme sheet the docs theme
 * imports.
 *
 * `toCss` registers concrete tokens as global `@property` initial-values and emits only contextual
 * (`light-dark()`/`var()`) tokens as scoped declarations, so a plain `toCss({ scope })` per theme
 * would not switch the concrete tokens (their `@property` registrations would collide). Instead we
 * emit the default theme (rebrand) in full — `@property` registrations + `:root` defaults — then, for
 * each other theme, a `:root[data-pantoken-theme="…"]` block that re-declares only the tokens whose
 * value DIFFERS from the default (the shared majority falls through to the base). Toggling the
 * attribute on `<html>` swaps the `--instui-*` set, which the `@pantoken/vitepress` bridge maps onto
 * `--vp-*`, re-theming the whole site. Runs in `docs:assets`, before `vitepress dev`/`build`.
 */
import { copyFileSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
// Import from SOURCE (build-time docs script, never shipped to the browser), not the `@pantoken/css` /
// `@pantoken/tokens` package specifiers (which resolve to `dist`, only rebuilt by the nested-forbidden
// `vp pack`). The token IR lives in `formats/tokens/generated/*.json` (which the src barrel reads), so a
// token-value edit — or a `toCss` emitter change — re-themes every preview live once this reruns.
import { toCss } from "../../../formats/css/src/index.ts";
import { byTheme, themes } from "../../../formats/tokens/src/index.ts";

type ThemeKey = keyof typeof themes;
const DEFAULT_THEME: ThemeKey = "rebrand";

const docsRoot = join(import.meta.dirname, "..");
const out = join(docsRoot, ".vitepress", "theme", "generated", "site-themes.css");
mkdirSync(dirname(out), { recursive: true });

// The default theme: @property registrations (concrete tokens) + :root declarations (contextual).
const base = toCss(byTheme(DEFAULT_THEME));

// Every other theme: only the tokens whose value differs from the default, scoped to the attribute.
const baseValue = new Map(byTheme(DEFAULT_THEME).map((t) => [t.name, t.value]));
const overrides = (Object.keys(themes) as ThemeKey[])
  .filter((theme) => theme !== DEFAULT_THEME)
  .map((theme) => {
    const decls = byTheme(theme)
      .filter((t) => baseValue.get(t.name) !== t.value)
      .map((t) => `  ${t.name}: ${t.value};`)
      .join("\n");
    return `:root[data-pantoken-theme="${theme}"] {\n${decls}\n}`;
  });

const css = [base, ...overrides].join("\n\n");
writeFileSync(out, css);
// Mirror into demos-assets so the `/play` runner loads the same token sheet. The theme imports `out`
// directly (module-graph HMR); this copy is what the iframes fetch by URL. mkdirSync keeps a clean-tree
// run (site-themes runs before demos.ts stages public/) from failing.
const assetsCopy = join(docsRoot, "public", "demos-assets", "site-themes.css");
mkdirSync(dirname(assetsCopy), { recursive: true });
copyFileSync(out, assetsCopy);
console.log(
  `✓ site-themes: wrote site-themes.css (${Object.keys(themes).length} themes, ${Math.round(css.length / 1024)}kb)`,
);

/**
 * Copy the single-theme component stylesheets the `/play` runner loads into `public/demos-assets/`,
 * sourced from `formats/components/generated/*.css` — NOT the shipped `@pantoken/components/*.css`
 * (which resolves to `dist`).
 *
 * During `vpr docs:dev` the components `dist` is only rebuilt by `vp pack`, which can't run nested under
 * vitepress, so a `dist` copy would go stale on every source edit. The `generated/*.css` sheets are
 * written from source by `formats/components/scripts/generate.ts` on every orchestrator cascade, so
 * copying from there keeps the demo assets live. These sheets carry no `@media (--theme-*)` rules, so a
 * plain single-theme copy is correct (unlike `components.css`, which needs the multi-theme scoping in
 * `components-sheet.ts`).
 *
 * Runs in `docs:assets` (via `demos.ts`) and again on component edits during `docs:dev`: the config's
 * workspace orchestrator cascades to this script (as the `@pantoken/docs#component-assets` node) after
 * the components recompile + `generate`. Writing into `public/` triggers a Vite full reload, so the
 * embedded `/play` iframes refetch the updated CSS.
 *
 * @module
 */
import { copyFileSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
// Source import (build-time docs script, never shipped to the browser) so the focus-outline sheet
// tracks focus.ts edits live via the components cascade. focus.ts lives under formats/components/src,
// so the `#styles → generate → component-assets` cascade reruns this on a focus edit.
import { focusOutlineCss } from "../../../formats/components/src/declarations/focus.ts";

const docsRoot = join(import.meta.dirname, "..");
const repoRoot = join(docsRoot, "..");
const generatedDir = join(repoRoot, "formats", "components", "generated");
const assetsDir = join(docsRoot, "public", "demos-assets");

/** The single-theme component sheets the `/play` runner injects (components.css is handled separately). */
const SHEETS = ["base", "prose", "icons", "select", "utilities"] as const;

/**
 * Copy each `generated/<name>.css` into `public/demos-assets/`, and write `focus-outline.css` from the
 * source `focusOutlineCss()` (the standalone ring the site `<head>` links and the `/play` runner load;
 * it isn't a shipped file, only inlined into base.css). Returns the written paths.
 */
export function stageComponentAssets(): string[] {
  mkdirSync(assetsDir, { recursive: true });
  const copied = SHEETS.map((name) => {
    const out = join(assetsDir, `${name}.css`);
    copyFileSync(join(generatedDir, `${name}.css`), out);
    return out;
  });
  const focusOut = join(assetsDir, "focus-outline.css");
  writeFileSync(focusOut, focusOutlineCss());
  return [...copied, focusOut];
}

// Run when invoked directly (`node scripts/stage-component-assets.ts`) — the docs:dev watch path. When
// imported by `demos.ts`, only the export is used.
if (import.meta.url === `file://${process.argv[1]}`) {
  const written = stageComponentAssets();
  console.log(`✓ component-assets: staged ${String(written.length)} sheet(s) to public/demos-assets/`);
}

